  def genTestCase(observationKind: ObservationKind.Type, preContainer: Option[String], postContainer: Option[String], testNameSuffix: Option[String]): ST = {
    val tq = "\"\"\""
    val suffix: String =
      if (testNameSuffix.nonEmpty) testNameSuffix.get
      else ""

    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.BatteryEvidenceChargeQualificationSupervisor_Instance_supervisorProcess_batteryEvidenceQualifier_postInit =>
        return (st"""// Begin test cases for BatteryEvidenceChargeQualificationSupervisor_Instance_supervisorProcess_batteryEvidenceQualifier_postInit
                    |
                    |test(s"BatteryEvidenceChargeQualificationSupervisor_Instance_supervisorProcess_batteryEvidenceQualifier_postInit: Check Post-condition$suffix") {
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val postContainer = scp_candidate.JSON.toBattery_Evidence_Charge_Qualification_SupervisorBatteryEvidenceQualifier_supervisorProcess_batteryEvidenceQualifier_PostState_Container_PS(postJson).left
                    |  assert(scp_candidate.Battery_Evidence_Charge_Qualification_Supervisor.BatteryEvidenceQualifier_supervisorProcess_batteryEvidenceQualifier_GumboX.inititialize_IEP_Post_Container(postContainer))
                    |}
                    |// End test cases for BatteryEvidenceChargeQualificationSupervisor_Instance_supervisorProcess_batteryEvidenceQualifier_postInit""")
      case scp_candidate.runtimemonitor.ObservationKind.BatteryEvidenceChargeQualificationSupervisor_Instance_supervisorProcess_batteryEvidenceQualifier_postCompute =>
        return (st"""// Begin test cases for BatteryEvidenceChargeQualificationSupervisor_Instance_supervisorProcess_batteryEvidenceQualifier_postCompute
                    |
                    |test(s"BatteryEvidenceChargeQualificationSupervisor_Instance_supervisorProcess_batteryEvidenceQualifier_postCompute: Check Post-condition$suffix") {
